<?php $fields=[['Admission Date','date_of_admission'],['Discount','discount_in_fee'],['Mobile','mobile'],['Date of Birth','date_of_birth'],['Gender','gender'],['Father','father_name'],['Mother','mother_name'],['Address','address']]; $initials=strtoupper(substr(preg_replace('/[^A-Za-z0-9]/','',(string)$student['student_name']),0,2)); ?>
