<header class="module-page__header student-profile-header"><div><nav class="breadcrumb" aria-label="Breadcrumb"><a href="<?= url('/admin/dashboard') ?>">Dashboard</a><i data-lucide="chevron-right"></i><a href="<?= url('/admin/students') ?>">Students</a><i data-lucide="chevron-right"></i><span aria-current="page">Profile</span></nav><h1>Student Profile</h1><p>View the complete record for this student.</p></div><div class="student-profile-actions"><a class="btn btn--secondary" href="<?= url('/admin/students') ?>"><i data-lucide="arrow-left"></i>Back to students</a><a class="btn btn--primary" href="<?= url('/admin/students/'.$student['id'].'/edit') ?>"><i data-lucide="pencil"></i>Edit Student</a></div></header>
<section class="student-profile-hero module-card"><div class="student-profile-avatar"><?= e($initials) ?></div><div class="student-profile-identity"><span class="section-kicker">Student record</span><h2><?= e($student['student_name']) ?></h2><p><?= e($student['registration_no']) ?> <span>•</span> <?= e($student['class_name']) ?></p></div><span class="student-status student-status--<?= e($student['status']) ?>"><?= e(ucfirst($student['status'])) ?></span></section>
